class Solution:
    def findPoisonedDuration(self, timeSeries: list[int], duration: int) -> int:
        total, end = 0, 0
        for time in timeSeries:
            finish = time + duration
            total += max(0, finish - max(time, end))
            end = max(end, finish)
        return total
